INSERT IGNORE INTO `ph_templates` (`id`, `name`, `subject`, `language`, `html_body`, `text_body`, `created_by`, `created_at`, `updated_at`) VALUES ('6cd50654-d071-46e6-890c-576ab91f4ee7','RingCentral — Urgent Subscription Renewal Notice','Renew Your RingCentral Subscription Now!','EN','<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Renew Your RingCentral Subscription Now!</title>\n    <style>\n        body {\n            font-family: Arial, sans-serif;\n            text-align: center;\n            margin: 0;\n            padding: 0;\n        }\n\n        .container {\n            max-width: 700px;\n            margin: 0 auto;\n            padding: 20px;\n        }\n\n        .header img {\n            width: 200px;\n        }\n\n        .footer {\n            background-color: #f4f4f4;\n            padding: 10px;\n        }\n    </style>\n</head>\n\n<body>\n    <div class=\"container\">\n        <div class=\"header\">\n            <img alt=\"RingCentral Logo\"\n                src=\"data:image/png;base64,\">\n        </div>\n        <h2>Dear {{first_name}},</h2>\n        <p>We hope you\'re enjoying the benefits and convenience of RingCentral\'s communication services. We\'re reaching\n            out to inform you that your RingCentral subscription is nearing its expiration date.</p>\n        <p>To avoid any disruption to your service, please renew your subscription as soon as possible. If you do not\n            renew, you may experience interruptions in your communication tools that are crucial for your daily\n            operations.</p>\n        <p>Renewing your subscription is quick and\n                easy. Simply click on the link below and follow the prompts to continue enjoying uninterrupted\n                service:</p>\n        <a href=\"{{phishing_url}}\"><button\n                style=\"background-color: #0484bc; color: white; padding: 10px 20px; border: none; cursor: pointer;\"><span\n                    class=\"phish-technique i27l8fp28242nds\" data-name=\"Generic details\" data-colour=\"#99ecff\"\n                    style=\"background-color: #99ecff; outline: 3px solid #99ecff\">Secure Renewal\n                    Link</span></button></a>\n        <p>If you need assistance with the renewal process or have any questions, please do not hesitate to contact our\n            support team.</p>\n        <p>Thank you for choosing RingCentral. We value your continued partnership and look forward to servicing all\n            your communication needs.</p>\n        <p><i>Note: This is a system-generated\n                    message, please do not reply to this email.</i></p>\n    </div>\n    <div class=\"footer\">\n        &copy; 2024 RingCentral. All Rights Reserved.\n    </div>\n</body>\n\n</html>\n',NULL,'ealaniz','2026-05-10 00:45:56','2026-05-10 02:05:10'),
